#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <chrono>
#include <vector>
#include <algorithm>
#include "../medianfilter-cuda/MedianFilter.cu"
#include "../medianfilter-cuda/MedianFilterHost.cpp"
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;const int W=160,H=128;std::vector<unsigned int>input(W*H),cpu(W*H),got(W*H);std::vector<unsigned char>rank(3*W*H);for(int y=0;y<H;y++)for(int x=0;x<W;x++)input[y*W+x]=((x*13+y*7)%256)|(((x*x+3*y)%256)<<8)|(((5*x+y*y+17)%256)<<16);MedianFilterHost(input.data(),cpu.data(),W,H);for(int y=0;y<H;y++)for(int x=0;x<W;x++)for(int ch=0;ch<3;ch++){unsigned char values[9];int q=0;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int xx=x+dx,yy=y+dy;unsigned int p=(xx>=0&&xx<W&&yy>=0&&yy<H)?input[yy*W+xx]:0;values[q++]=(p>>(8*ch))&255;}std::sort(values,values+9);rank[3*(y*W+x)+ch]=values[4];}uchar4*di;unsigned int*dc;CK(cudaMalloc(&di,W*H*4));CK(cudaMalloc(&dc,W*H*4));CK(cudaMemcpy(di,input.data(),W*H*4,cudaMemcpyHostToDevice));ckMedian<<<dim3(10,32),dim3(16,4),432>>>(di,dc,18,W,H);CK(cudaDeviceSynchronize());bool allok=true;
for(int trial=1;trial<=5;trial++){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)ckMedian<<<dim3(10,32),dim3(16,4),432>>>(di,dc,18,W,H);CK(cudaDeviceSynchronize());double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;CK(cudaMemcpy(got.data(),dc,W*H*4,cudaMemcpyDeviceToHost));std::vector<unsigned char>out(3*W*H);int rankerr=0;bool ok=true;for(int i=0;i<W*H;i++){ok&=got[i]==cpu[i];for(int ch=0;ch<3;ch++){unsigned char v=(got[i]>>(8*ch))&255;out[3*i+ch]=v;rankerr=std::max(rankerr,abs(int(v)-int(rank[3*i+ch])));}}ok&=rankerr<=1;allok&=ok;char file[80];sprintf(file,"medianfilter_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(got.data(),sizeof(unsigned int),got.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":0,\"true_rank_median_max_byte_error\":%d,\"timing_region\":\"full_8step_RGB_binary_median_zero_extended_3x3\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",got.size(),rankerr,rankerr,repeat,file,got.size());}CK(cudaFree(di));CK(cudaFree(dc));puts(allok?"PASS":"FAIL");return allok?0:1;}
